actions.script:
let found = null
jobError = null
try { found = ec.service.sync().name('org.moqui.dev.DatabaseServices.get#DatabaseJobStatus').parameters({jobId: String(jobId || '')}).call() }
catch (e) { jobError = String(e.message || e) }
if (ec.message.hasError()) { jobError = ec.message.errorsString; ec.message.clearErrors() }
job = (found && found.job) || {}
const statuses = {DbjsPending: 'Pending', DbjsRunning: 'Running', DbjsDone: 'Done', DbjsFailed: 'Failed', DbjsCancelled: 'Cancelled', DbjsSkipped: 'Skipped'}
jobStatus = statuses[job.statusId] || job.statusId || ''
const progress = (found && found.progress) || []
const blocking = (found && found.blocking) || []
statementList = ((found && found.statements) || []).map((statement) => {
    const running = statement.statusId == 'DbjsRunning' && statement.backendPid
    const rows = running ? progress.filter((row) => String(row.pid) == String(statement.backendPid)) : []
    const blockers = running ? blocking.filter((session) => session.blocked_pid == null || String(session.blocked_pid) == String(statement.backendPid)) : []
    return {statementSeqId: statement.statementSeqId, status: statuses[statement.statusId] || statement.statusId || '',
        statementText: statement.statementText || '', errorText: statement.errorText || '',
        progress: rows.map((row) => [row.command, row.phase, row.progress != null ? row.progress + '%'
            : row.blocks_total ? Math.round(100 * Number(row.blocks_done || 0) / Number(row.blocks_total)) + '%' : ''].filter(Boolean).join(' ')).join('; '),
        blockedBy: blockers.map((session) => session.pid + ' (' + (session.user_name || '') + ')').join(', ')}
})
canAdmin = ec.user.hasPermission('DATABASE_ADMIN')
